import csv
import json
import math
import os

from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"


def load_data():
    with open(os.path.join(DATA, "config.json")) as f:
        cfg = json.load(f)

    bases = {}
    with open(os.path.join(DATA, "candidate_bases.csv")) as f:
        for row in csv.DictReader(f):
            b = row["base_id"]
            bases[b] = {
                "region": row["region"],
                "x": float(row["x_km"]),
                "y": float(row["y_km"]),
                "fixed_cost": float(row["fixed_cost"]),
                "max_drones": int(row["max_drones"]),
                "kit_capacity": int(row["kit_capacity"]),
                "launch_delay": float(row["launch_delay_min"]),
                "range": float(row["range_km"]),
                "hardened": int(row["weather_hardened"]),
            }

    zones = {}
    with open(os.path.join(DATA, "demand_zones.csv")) as f:
        for row in csv.DictReader(f):
            z = row["zone_id"]
            zones[z] = {
                "district": row["district"],
                "equity": row["equity_group"],
                "x": float(row["x_km"]),
                "y": float(row["y_km"]),
                "calls": float(row["base_calls_per_day"]),
                "risk": float(row["risk_weight"]),
                "ems": float(row["baseline_ems_min"]),
                "hp": int(row["priority_zone"]),
            }

    scenarios = {}
    with open(os.path.join(DATA, "scenarios.csv")) as f:
        for row in csv.DictReader(f):
            s = row["scenario_id"]
            scenarios[s] = {
                "prob": float(row["probability"]),
                "call_mult": float(row["call_multiplier"]),
                "speed_mult": float(row["drone_speed_multiplier"]),
                "ground_mult": float(row["ground_time_multiplier"]),
                "kit_reserve": float(row["kit_reserve_factor"]),
                "no_fly": int(row["no_fly"]),
            }

    corridors = {}
    with open(os.path.join(DATA, "air_corridor_rules.csv")) as f:
        for row in csv.DictReader(f):
            key = (row["origin_region"], row["destination_district"])
            cap = float(row["max_calls_per_day"])
            extra = float(row["extra_minutes"])
            hard = int(row["requires_weather_hardened"])
            if row["scenario_id"] == "ALL":
                corridors.setdefault(key, {})["ALL"] = (cap, extra, hard)
            else:
                corridors.setdefault(key, {})[row["scenario_id"]] = (cap, extra, hard)

    exceptions = set()
    with open(os.path.join(DATA, "base_zone_exceptions.csv")) as f:
        for row in csv.DictReader(f):
            if int(row["allowed"]) == 0:
                exceptions.add((row["scenario_id"], row["base_id"], row["zone_id"]))

    ground_cap = {}
    with open(os.path.join(DATA, "district_ground_capacity.csv")) as f:
        for row in csv.DictReader(f):
            ground_cap[(row["scenario_id"], row["district"])] = float(
                row["max_ground_calls_per_day"]
            )

    staffing = {}
    with open(os.path.join(DATA, "base_region_staffing.csv")) as f:
        for row in csv.DictReader(f):
            staffing[row["region"]] = {
                "max_bases": int(row["max_open_bases"]),
                "max_drones": int(row["max_drones"]),
            }

    equity = {}
    with open(os.path.join(DATA, "equity_requirements.csv")) as f:
        for row in csv.DictReader(f):
            equity[row["equity_group"]] = {
                "target": float(row["response_target_min"]),
                "min_share": float(row["min_fast_share"]),
                "tail_share": float(row["tail_min_fast_share"]),
            }

    return cfg, bases, zones, scenarios, corridors, exceptions, ground_cap, staffing, equity


def build_precomputed(cfg, bases, zones, scenarios, corridors, exceptions):
    B = sorted(bases)
    Z = sorted(zones)
    S = sorted(scenarios)

    # corridor rule per (scenario, region, district)
    cor = {}
    for (r, d), table in corridors.items():
        for s in S:
            if s in table:
                cor[(s, r, d)] = table[s]
            else:
                cor[(s, r, d)] = table["ALL"]

    dist = {}
    for b in B:
        for z in Z:
            dx = bases[b]["x"] - zones[z]["x"]
            dy = bases[b]["y"] - zones[z]["y"]
            dist[(b, z)] = math.hypot(dx, dy)

    # eligibility and response times
    elig = {}
    dtime = {}
    for s in S:
        sc = scenarios[s]
        for b in B:
            for z in Z:
                if sc["no_fly"]:
                    continue
                if dist[(b, z)] > bases[b]["range"] + 1e-9:
                    continue
                if (s, b, z) in exceptions or ("ALL", b, z) in exceptions:
                    continue
                r = bases[b]["region"]
                d = zones[z]["district"]
                cap, extra, hard = cor[(s, r, d)]
                if hard and not bases[b]["hardened"]:
                    continue
                elig[(s, z, b)] = True
                t = bases[b]["launch_delay"] + 60.0 * dist[(b, z)] / (
                    cfg["base_drone_speed_kmph"] * sc["speed_mult"]
                ) + extra
                dtime[(s, z, b)] = t

    gtime = {}
    for s in S:
        for z in Z:
            gtime[(s, z)] = zones[z]["ems"] * scenarios[s]["ground_mult"]

    # tail scenarios: two lowest probability
    tail = sorted(S, key=lambda s: scenarios[s]["prob"])[: cfg["tail_scenario_count"]]

    return B, Z, S, cor, dist, elig, dtime, gtime, tail


def solve():
    cfg, bases, zones, scenarios, corridors, exceptions, ground_cap, staffing, equity = load_data()
    B, Z, S, cor, dist, elig, dtime, gtime, tail = build_precomputed(
        cfg, bases, zones, scenarios, corridors, exceptions
    )

    w_cost = cfg["weights"]["weekly_cost"]
    w_exp = cfg["weights"]["expected_response_minutes"]
    w_tail = cfg["weights"]["tail_response_minutes"]
    w_mort = cfg["weights"]["mortality_risk"]
    w_eq = cfg["weights"]["equity_gap"]
    w_gnd = cfg["weights"]["ground_fallback"]
    decay = cfg["death_risk_decay_per_minute"]
    service = cfg["service_minutes_at_scene"] + cfg["reload_minutes"]
    day_minutes = cfg["daily_service_hours"] * 60.0
    util_cap = cfg["max_queue_utilization"]

    model = Model("naloxone_drone")
    model.setParam("gaprel", 0.0005)
    time_limit = 300.0
    env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env is not None:
        try:
            time_limit = min(time_limit, float(env))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    y = {}
    u = {}
    v = {}
    for b in B:
        y[b] = model.addVar(name=f"y_{b}", vtype="B", lb=0, ub=1, obj=0.0)
        u[b] = model.addVar(
            name=f"u_{b}", vtype="I", lb=0, ub=bases[b]["max_drones"], obj=0.0
        )
        v[b] = model.addVar(
            name=f"v_{b}", vtype="I", lb=0, ub=bases[b]["kit_capacity"], obj=0.0
        )

    x = {}
    w = {}
    q = {}
    for s in S:
        for z in Z:
            w[(s, z)] = model.addVar(name=f"w_{s}_{z}", vtype="B", lb=0, ub=1, obj=0.0)
            for b in B:
                if (s, z, b) in elig:
                    x[(s, z, b)] = model.addVar(
                        name=f"x_{s}_{z}_{b}", vtype="B", lb=0, ub=1, obj=0.0
                    )
                    if zones[z]["hp"] and not scenarios[s]["no_fly"]:
                        q[(s, z, b)] = model.addVar(
                            name=f"q_{s}_{z}_{b}", vtype="B", lb=0, ub=1, obj=0.0
                        )

    # equity shortfall vars
    h = {}
    for s in S:
        for g in equity:
            h[(s, g)] = model.addVar(name=f"h_{s}_{g}", vtype="C", lb=0, ub=None, obj=0.0)

    cons = []

    # open base count and regional staffing
    cons.append(model.addCons(quicksum(y[b] for b in B) >= cfg["min_open_bases"], "min_open"))
    cons.append(model.addCons(quicksum(y[b] for b in B) <= cfg["max_open_bases"], "max_open"))
    for r, st in staffing.items():
        rb = [b for b in B if bases[b]["region"] == r]
        if not rb:
            continue
        cons.append(model.addCons(quicksum(y[b] for b in rb) <= st["max_bases"], f"reg_bases_{r}"))
        cons.append(model.addCons(quicksum(u[b] for b in rb) <= st["max_drones"], f"reg_drones_{r}"))

    # fleet
    cons.append(model.addCons(quicksum(u[b] for b in B) <= cfg["total_drones_available"], "fleet"))
    for b in B:
        cons.append(model.addCons(u[b] <= bases[b]["max_drones"] * y[b], f"u_cap_{b}"))
        cons.append(model.addCons(u[b] >= y[b], f"u_min_{b}"))
        cons.append(model.addCons(v[b] <= bases[b]["kit_capacity"] * y[b], f"v_cap_{b}"))

    # budget
    budget_expr = quicksum(
        bases[b]["fixed_cost"] * y[b] + cfg["drone_weekly_cost"] * u[b] + cfg["kit_unit_cost"] * v[b]
        for b in B
    )
    cons.append(model.addCons(budget_expr <= cfg["weekly_budget"], "budget"))

    # dispatch
    for s in S:
        for z in Z:
            terms = [w[(s, z)]] + [x[(s, z, b)] for b in B if (s, z, b) in elig]
            cons.append(model.addCons(quicksum(terms) == 1, f"dispatch_{s}_{z}"))
            for b in B:
                if (s, z, b) in elig:
                    cons.append(model.addCons(x[(s, z, b)] <= y[b], f"xy_{s}_{z}_{b}"))

    # corridor capacity
    for s in S:
        mc = scenarios[s]["call_mult"]
        for (r, d), rb in [
            (r, d, [b for b in B if bases[b]["region"] == r])
            for r in set(bases[b]["region"] for b in B)
            for d in set(zones[z]["district"] for z in Z)
        ]:
            terms = [
                zones[z]["calls"] * mc * x[(s, z, b)]
                for b in rb
                for z in Z
                if zones[z]["district"] == d and (s, z, b) in elig
            ]
            if terms:
                cap, _, _ = cor[(s, r, d)]
                cons.append(model.addCons(quicksum(terms) <= cap, f"cor_{s}_{r}_{d}"))

    # ground capacity and share
    for s in S:
        mc = scenarios[s]["call_mult"]
        for d in set(zones[z]["district"] for z in Z):
            dz = [z for z in Z if zones[z]["district"] == d]
            terms = [zones[z]["calls"] * mc * w[(s, z)] for z in dz]
            cons.append(
                model.addCons(quicksum(terms) <= ground_cap[(s, d)], f"gcap_{s}_{d}")
            )
        if not scenarios[s]["no_fly"]:
            total = quicksum(zones[z]["calls"] * mc * w[(s, z)] for z in Z)
            denom = sum(zones[z]["calls"] for z in Z) * mc
            cons.append(
                model.addCons(total <= cfg["max_ground_share_flyable"] * denom, f"gshare_{s}")
            )

    # backup
    for s in S:
        if scenarios[s]["no_fly"]:
            continue
        for z in Z:
            if not zones[z]["hp"]:
                continue
            elig_bs = [b for b in B if (s, z, b) in elig]
            if not elig_bs:
                continue
            cons.append(
                model.addCons(
                    quicksum(q[(s, z, b)] for b in elig_bs)
                    >= quicksum(x[(s, z, b)] for b in elig_bs),
                    f"backup_{s}_{z}",
                )
            )
            for b in elig_bs:
                cons.append(model.addCons(q[(s, z, b)] <= y[b], f"qy_{s}_{z}_{b}"))
                cons.append(model.addCons(q[(s, z, b)] <= 1 - x[(s, z, b)], f"qneq_{s}_{z}_{b}"))

    # utilization and kits
    for s in S:
        mc = scenarios[s]["call_mult"]
        for b in B:
            terms = [
                zones[z]["calls"] * mc * x[(s, z, b)]
                for z in Z
                if (s, z, b) in elig
            ]
            if not terms:
                continue
            load = quicksum(terms)
            cons.append(
                model.addCons(
                    service / day_minutes * load <= util_cap * u[b], f"util_{s}_{b}"
                )
            )
            cons.append(
                model.addCons(
                    scenarios[s]["kit_reserve"] * load <= v[b], f"kits_{s}_{b}"
                )
            )

    # equity
    groups = sorted(equity)
    for g in groups:
        gz = [z for z in Z if zones[z]["equity"] == g]
        tgt = equity[g]["target"]
        min_share = equity[g]["min_share"]
        # expected
        fast = 0.0
        tot = 0.0
        for s in S:
            mc = scenarios[s]["call_mult"]
            p = scenarios[s]["prob"]
            for z in gz:
                tot += p * zones[z]["calls"] * mc
                for b in B:
                    if (s, z, b) in elig and dtime[(s, z, b)] <= tgt + 1e-9:
                        fast += p * zones[z]["calls"] * mc * x[(s, z, b)]
                if gtime[(s, z)] <= tgt + 1e-9:
                    fast += p * zones[z]["calls"] * mc * w[(s, z)]
        cons.append(model.addCons(fast >= min_share * tot, f"eq_exp_{g}"))
        # tail
        for s in tail:
            mc = scenarios[s]["call_mult"]
            fast_s = 0.0
            tot_s = 0.0
            for z in gz:
                tot_s += zones[z]["calls"] * mc
                for b in B:
                    if (s, z, b) in elig and dtime[(s, z, b)] <= tgt + 1e-9:
                        fast_s += zones[z]["calls"] * mc * x[(s, z, b)]
                if gtime[(s, z)] <= tgt + 1e-9:
                    fast_s += zones[z]["calls"] * mc * w[(s, z)]
            cons.append(model.addCons(fast_s >= equity[g]["tail_share"] * tot_s, f"eq_tail_{g}_{s}"))

    # objective
    cost_expr = budget_expr
    exp_resp = 0.0
    tail_resp = 0.0
    mort = 0.0
    gnd = 0.0
    for s in S:
        p = scenarios[s]["prob"]
        mc = scenarios[s]["call_mult"]
        for z in Z:
            cz = zones[z]["calls"] * mc
            for b in B:
                if (s, z, b) in elig:
                    t = dtime[(s, z, b)]
                    exp_resp += p * cz * t * x[(s, z, b)]
                    mort += p * cz * zones[z]["risk"] * decay * t * x[(s, z, b)]
                    if s in tail:
                        tail_resp += cz * t * x[(s, z, b)]
            tg = gtime[(s, z)]
            exp_resp += p * cz * tg * w[(s, z)]
            mort += p * cz * zones[z]["risk"] * decay * tg * w[(s, z)]
            gnd += p * cz * w[(s, z)]
            if s in tail:
                tail_resp += cz * tg * w[(s, z)]

    obj = (
        w_cost * cost_expr
        + w_exp * exp_resp
        + w_tail * tail_resp
        + w_mort * mort
        + w_eq * quicksum(h[(s, g)] for s in S for g in groups)
        + w_gnd * gnd
    )
    model.setObjective(obj, sense="minimize")

    model.optimize()

    status = model.getStatus()
    print(f"Solver status: {status}")
    nsols = model.getNSols()
    print(f"Number of solutions: {nsols}")
    obj_val = None
    if nsols > 0:
        obj_val = model.getObjVal()
        print(f"Objective: {obj_val:.8f}")

    # extract solution
    sol = {
        "y": {},
        "u": {},
        "v": {},
        "x": {},
        "w": {},
        "q": {},
    }
    if nsols > 0:
        for b in B:
            sol["y"][b] = int(round(model.getVal(y[b])))
            sol["u"][b] = int(round(model.getVal(u[b])))
            sol["v"][b] = int(round(model.getVal(v[b])))
        for s in S:
            for z in Z:
                sol["w"][(s, z)] = int(round(model.getVal(w[(s, z)])))
                for b in B:
                    if (s, z, b) in elig:
                        val = int(round(model.getVal(x[(s, z, b)])))
                        sol["x"][(s, z, b)] = val
                        if (s, z, b) in q:
                            sol["q"][(s, z, b)] = int(round(model.getVal(q[(s, z, b)])))
    else:
        # best effort: no solution
        for b in B:
            sol["y"][b] = 0
            sol["u"][b] = 0
            sol["v"][b] = 0
        for s in S:
            for z in Z:
                sol["w"][(s, z)] = 1
                for b in B:
                    if (s, z, b) in elig:
                        sol["x"][(s, z, b)] = 0
                        if (s, z, b) in q:
                            sol["q"][(s, z, b)] = 0

    # validation
    ok = True
    def check(cond, msg):
        nonlocal ok
        if not cond:
            ok = False
            print(f"FAIL: {msg}")

    # base rows
    for b in B:
        check(sol["y"][b] in (0, 1), f"y[{b}] not binary")
        check(0 <= sol["u"][b] <= bases[b]["max_drones"], f"u[{b}] out of range")
        check(0 <= sol["v"][b] <= bases[b]["kit_capacity"], f"v[{b}] out of range")
        if sol["y"][b] == 0:
            check(sol["u"][b] == 0 and sol["v"][b] == 0, f"closed base {b} holds resources")
    check(cfg["min_open_bases"] <= sum(sol["y"].values()) <= cfg["max_open_bases"], "open count")
    check(sum(sol["u"].values()) <= cfg["total_drones_available"], "fleet total")
    for r, st in staffing.items():
        rb = [b for b in B if bases[b]["region"] == r]
        check(sum(sol["y"][b] for b in rb) <= st["max_bases"], f"region bases {r}")
        check(sum(sol["u"][b] for b in rb) <= st["max_drones"], f"region drones {r}")
    tot_cost = sum(
        bases[b]["fixed_cost"] * sol["y"][b]
        + cfg["drone_weekly_cost"] * sol["u"][b]
        + cfg["kit_unit_cost"] * sol["v"][b]
        for b in B
    )
    check(tot_cost <= cfg["weekly_budget"] + 1e-6, "budget")

    for s in S:
        mc = scenarios[s]["call_mult"]
        for z in Z:
            served = sol["w"][(s, z)] + sum(
                sol["x"].get((s, z, b), 0) for b in B
            )
            check(served == 1, f"dispatch {s},{z} sum={served}")
            if sol["w"][(s, z)] == 0:
                pb = [b for b in B if sol["x"].get((s, z, b), 0) == 1]
                check(len(pb) == 1, f"primary base {s},{z}")
                if pb:
                    b = pb[0]
                    check(sol["y"][b] == 1, f"primary base closed {s},{z},{b}")
                    check((s, z, b) in elig, f"ineligible primary {s},{z},{b}")
                    if zones[z]["hp"] and not scenarios[s]["no_fly"]:
                        bq = [bb for bb in B if sol["q"].get((s, z, bb), 0) == 1]
                        check(len(bq) == 1, f"backup missing {s},{z}")
                        if bq:
                            bb = bq[0]
                            check(bb != b, f"backup equals primary {s},{z}")
                            check(sol["y"][bb] == 1, f"backup closed {s},{z},{bb}")
                            check((s, z, bb) in elig, f"backup ineligible {s},{z},{bb}")
        # corridor
        for r in set(bases[b]["region"] for b in B):
            for d in set(zones[z]["district"] for z in Z):
                load = sum(
                    zones[z]["calls"] * mc * sol["x"].get((s, z, b), 0)
                    for b in B
                    if bases[b]["region"] == r
                    for z in Z
                    if zones[z]["district"] == d
                )
                cap, _, _ = cor[(s, r, d)]
                check(load <= cap + 1e-6, f"corridor {s},{r},{d}: {load}>{cap}")
        # ground
        for d in set(zones[z]["district"] for z in Z):
            load = sum(
                zones[z]["calls"] * mc * sol["w"][(s, z)]
                for z in Z
                if zones[z]["district"] == d
            )
            check(load <= ground_cap[(s, d)] + 1e-6, f"ground cap {s},{d}")
        if not scenarios[s]["no_fly"]:
            total_g = sum(zones[z]["calls"] * mc * sol["w"][(s, z)] for z in Z)
            denom = sum(zones[z]["calls"] for z in Z) * mc
            check(total_g <= cfg["max_ground_share_flyable"] * denom + 1e-6, f"ground share {s}")
        # utilization and kits
        for b in B:
            load = sum(
                zones[z]["calls"] * mc * sol["x"].get((s, z, b), 0) for z in Z
            )
            if sol["y"][b] == 1:
                check(service / day_minutes * load <= util_cap * sol["u"][b] + 1e-6, f"util {s},{b}")
                check(scenarios[s]["kit_reserve"] * load <= sol["v"][b] + 1e-6, f"kits {s},{b}")

    # equity
    for g in groups:
        gz = [z for z in Z if zones[z]["equity"] == g]
        tgt = equity[g]["target"]
        fast = 0.0
        tot = 0.0
        for s in S:
            mc = scenarios[s]["call_mult"]
            p = scenarios[s]["prob"]
            for z in gz:
                tot += p * zones[z]["calls"] * mc
                for b in B:
                    if (s, z, b) in elig and dtime[(s, z, b)] <= tgt + 1e-9:
                        fast += p * zones[z]["calls"] * mc * sol["x"].get((s, z, b), 0)
                if gtime[(s, z)] <= tgt + 1e-9:
                    fast += p * zones[z]["calls"] * mc * sol["w"][(s, z)]
        check(fast >= equity[g]["min_share"] * tot - 1e-6, f"equity expected {g}")
        for s in tail:
            mc = scenarios[s]["call_mult"]
            fast_s = 0.0
            tot_s = 0.0
            for z in gz:
                tot_s += zones[z]["calls"] * mc
                for b in B:
                    if (s, z, b) in elig and dtime[(s, z, b)] <= tgt + 1e-9:
                        fast_s += zones[z]["calls"] * mc * sol["x"].get((s, z, b), 0)
                if gtime[(s, z)] <= tgt + 1e-9:
                    fast_s += zones[z]["calls"] * mc * sol["w"][(s, z)]
            check(fast_s >= equity[g]["tail_share"] * tot_s - 1e-6, f"equity tail {g} {s}")

    print("Validation:", "PASS" if ok else "FAIL")

    # write solution
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", newline="") as f:
        wr = csv.writer(f)
        wr.writerow(["row_type", "scenario_id", "zone_id", "base_id", "backup_base_id", "drones", "kits", "mode", "priority"])
        for b in B:
            if sol["y"][b] == 1:
                wr.writerow(["base", "", "", b, "", str(sol["u"][b]), str(sol["v"][b]), "open", ""])
            else:
                wr.writerow(["base", "", "", b, "", "0", "0", "closed", ""])
        for s in S:
            for z in Z:
                if sol["w"][(s, z)] == 1:
                    wr.writerow(["dispatch", s, z, "", "", "", "", "ground", "2"])
                else:
                    pb = [b for b in B if sol["x"].get((s, z, b), 0) == 1]
                    b = pb[0] if pb else ""
                    bb = ""
                    if zones[z]["hp"] and not scenarios[s]["no_fly"] and b:
                        bq = [bb2 for bb2 in B if sol["q"].get((s, z, bb2), 0) == 1]
                        bb = bq[0] if bq else ""
                    prio = "1" if (zones[z]["hp"] and b) else "3"
                    wr.writerow(["dispatch", s, z, b, bb, "", "", "drone", prio])
    print(f"Wrote {OUT}")
    return status, obj_val


